//! 🏗️ Generated owned receivers retain typed fields and remaining original records between admitted turns.
use super::*;

fn fields_cursor(name:&syn::Ident,visibility:&syn::Visibility,fields:&Fields,construct:proc_macro2::TokenStream,suffix:&str)->(proc_macro2::TokenStream,syn::Ident){
 let cursor=quote::format_ident!("__{}{}OwnedReceiving",name,suffix);let frame=quote::format_ident!("__{}{}OwnedFields",name,suffix);let active=quote::format_ident!("__{}{}OwnedChild",name,suffix);let plans=plan_fields(fields);let o=quote!(::semio_framework_dsl_record::receiving::owned);let v=quote!(::semio_framework_value);
 let declared=plans.iter().filter(|plan|!plan.skip).map(|plan|plan.id).collect::<Vec<_>>();let required=plans.iter().filter(|plan|!plan.skip).map(|plan|!plan.optional).collect::<Vec<_>>();
 let members=plans.iter().map(|plan|{let ident=&plan.ident;let ty=&plan.field_ty;quote!(#ident:Option<#ty>)}).collect::<Vec<_>>();let empty=plans.iter().map(|plan|{let ident=&plan.ident;quote!(#ident:None)}).collect::<Vec<_>>();let variants=plans.iter().enumerate().filter(|(_,plan)|!plan.skip).map(|(index,plan)|{let child=quote::format_ident!("Field{}",index);let ty=&plan.field_ty;quote!(#child(Box<<#ty as #o::DslOwnedReceivingField>::Cursor>))}).collect::<Vec<_>>();
 let demands_active=plans.iter().enumerate().filter(|(_,plan)|!plan.skip).map(|(index,plan)|{let child=quote::format_ident!("Field{}",index);let field=&plan.ident;let ty=&plan.field_ty;quote!(#active::#child(child)=>{if self.fields.value.as_ref().unwrap().#field.is_some(){return Ok(#v::RetirementDemand{release_bytes:std::mem::size_of::<<#ty as #o::DslOwnedReceivingField>::Cursor>(),depth:2,..Default::default()})}if child.is_ready(){return #o::nested(#o::metadata::<#ty>())}return child.demands(&self.current.value,body).and_then(#o::nested)})}).collect::<Vec<_>>();
 let demands_fields=plans.iter().enumerate().map(|(index,plan)|{let ty=&plan.field_ty;let id=plan.id;if plan.skip{return quote!(#index=>return Ok(#o::metadata::<#ty>()),)}let unwrap=if plan.block{quote!(let release=match value{Some(::semio_framework_dsl_record::FieldValue::Block(_))=>std::mem::size_of::<::semio_framework_dsl_record::FieldValue>(),None|Some(::semio_framework_dsl_record::FieldValue::Absent)=>0,_=>return Err(#o::invalid())};demand.release_bytes=release;)}else{quote!()};quote!(#index=>{let mut demand=#o::child_demand::<<#ty as #o::DslOwnedReceivingField>::Cursor>();let Some(::semio_framework_dsl_record::FieldValue::Record(record))=self.record.value.as_ref()else{return Err(#o::invariant())};let value=record.get(#id);#unwrap return Ok(demand)},)}).collect::<Vec<_>>();
 let step_active=plans.iter().enumerate().filter(|(_,plan)|!plan.skip).map(|(index,plan)|{let child=quote::format_ident!("Field{}",index);let field=&plan.ident;quote!(#active::#child(child)=>{if self.fields.value.as_ref().unwrap().#field.is_some(){native.checkpoint()?;if !child.terminal_is_empty(){return Err(#o::invariant())}self.active=#active::None;self.index+=1;return Ok(#o::receipt(demand))}if child.is_ready(){native.checkpoint()?;return child.take_into(&mut self.fields.value.as_mut().unwrap().#field,#o::child_grant(grant))}return child.step(&mut self.current.value,native,body,#o::child_grant(grant))})}).collect::<Vec<_>>();
 let step_fields=plans.iter().enumerate().map(|(index,plan)|{let field=&plan.ident;let id=plan.id;let ty=&plan.field_ty;if plan.skip{return quote!(#index=>{self.fields.value.as_mut().unwrap().#field=Some(None);self.index+=1;return Ok(#o::receipt(demand))},)}let child=quote::format_ident!("Field{}",index);let unwrap=if plan.block{quote!(let value=match value{::semio_framework_dsl_record::FieldValue::Block(inner)=>*inner,::semio_framework_dsl_record::FieldValue::Absent=>::semio_framework_dsl_record::FieldValue::Absent,_=>return Err(#o::invariant())};)}else{quote!()};quote!(#index=>{let child=#o::admit_child::<<#ty as #o::DslOwnedReceivingField>::Cursor>(native)?;let Some(::semio_framework_dsl_record::FieldValue::Record(record))=self.record.value.as_mut()else{return Err(#o::invariant())};let value=record.fields.get_mut(&#id).map_or(::semio_framework_dsl_record::FieldValue::Absent,|value|std::mem::replace(value,::semio_framework_dsl_record::FieldValue::Absent));#unwrap *self.current.value=Some(value);self.active=#active::#child(child);return Ok(#o::receipt(demand))},)}).collect::<Vec<_>>();
 let close_demands=plans.iter().enumerate().filter(|(_,plan)|!plan.skip).map(|(index,plan)|{let child=quote::format_ident!("Field{}",index);let ty=&plan.field_ty;quote!(#active::#child(child)=>return if child.terminal_is_empty(){Ok(#v::RetirementDemand{release_bytes:std::mem::size_of::<<#ty as #o::DslOwnedReceivingField>::Cursor>(),depth:2,..Default::default()})}else{child.close_demands(body).and_then(#o::nested)},)}).collect::<Vec<_>>();
 let close_step=plans.iter().enumerate().filter(|(_,plan)|!plan.skip).map(|(index,_)|{let child=quote::format_ident!("Field{}",index);quote!(#active::#child(child)=>{if !child.terminal_is_empty(){return child.close_step(#o::child_grant(grant))}let demand=self.close_demands(grant.maximum_copy_bytes)?;if !#o::funds(grant,demand){return Ok(Default::default())}self.active=#active::None;return Ok(#o::receipt(demand))},)}).collect::<Vec<_>>();
 let checks=plans.iter().map(|plan|{let field=&plan.ident;quote!(frame.#field.is_none())}).collect::<Vec<_>>();let inits=plans.iter().map(|plan|{let field=&plan.ident;quote!(#field:frame.#field.take().unwrap())}).collect::<Vec<_>>();let output=if matches!(fields,Fields::Unit){construct}else{quote!(#construct{#(#inits),*})};
 let definitions=quote!{
  #[derive(::semio_framework_value::RetireOwned)]struct #frame{#(#members),*}
  enum #active{None,#(#variants),*}
  #visibility struct #cursor{record:#o::OwnedSlot<::semio_framework_dsl_record::FieldValue>,current:#o::OwnedSlot<::semio_framework_dsl_record::FieldValue>,fields:#o::OwnedSlot<#frame>,output:#o::OwnedSlot<#name>,active:#active,shape:#o::DeclaredRecordShape,index:usize,initialized:bool,closing:bool}
  impl Default for #cursor{fn default()->Self{Self{record:Default::default(),current:Default::default(),fields:Default::default(),output:Default::default(),active:#active::None,shape:Default::default(),index:0,initialized:false,closing:false}}}
  impl #o::OwnedFieldReceiving<#name> for #cursor{
   fn demands(&self,_:&Option<::semio_framework_dsl_record::FieldValue>,body:usize)->Result<#v::RetirementDemand,#v::ValueError>{use #o::OwnedFieldReceiving as _;if !self.initialized{if !self.shape.is_ready(){return Ok(#o::metadata::<()>())}return Ok(#v::RetirementDemand{copy_bytes:std::mem::size_of::<#frame>()+std::mem::size_of::<::semio_framework_dsl_record::FieldValue>(),depth:1,..Default::default()})}match &self.active{#(#demands_active,)*#active::None=>{}}match self.index{#(#demands_fields)*_=>{}}if !self.record.terminal_is_empty(){return self.record.close_demands(body)}Ok(#o::metadata::<#name>())}
   fn step(&mut self,source:&mut Option<::semio_framework_dsl_record::FieldValue>,native:&mut #v::NativeDecodeControl<'_>,body:usize,grant:#v::RetainedCloneGrant)->Result<#v::RetainedCloneProgress,#v::ValueError>{use #o::OwnedFieldReceiving as _;if self.closing{return Err(#o::invariant())}if self.output.value.is_some(){return Ok(Default::default())}let demand=self.demands(source,body)?;if !#o::funds(grant,demand){return Ok(Default::default())}match &mut self.active{#(#step_active,)*#active::None=>{}}native.checkpoint()?;if !self.initialized{let Some(::semio_framework_dsl_record::FieldValue::Record(record))=source.as_ref()else{return Err(#o::invalid())};if !self.shape.is_ready(){return self.shape.step(record,&[#((#declared,#required)),*],native,grant)}*self.record.value=source.take();*self.fields.value=Some(#frame{#(#empty),*});self.initialized=true;return Ok(#o::receipt(demand))}match self.index{#(#step_fields)*_=>{}}if !self.record.terminal_is_empty(){return #o::close_source(&mut self.record,native,grant)}let frame=self.fields.value.as_ref().ok_or_else(#o::invariant)?;if false #(||#checks)*{return Err(#o::invariant())}let mut frame=self.fields.value.take().unwrap();*self.output.value=Some(#output);Ok(#o::receipt(demand))}
   fn is_ready(&self)->bool{!self.closing&&self.output.value.is_some()}
   fn take_into(&mut self,output:&mut Option<#name>,grant:#v::RetainedCloneGrant)->Result<#v::RetainedCloneProgress,#v::ValueError>{if self.closing||output.is_some()||self.output.value.is_none(){return Err(#o::invariant())}let demand=#o::metadata::<#name>();if !#o::funds(grant,demand){return Ok(Default::default())}*output=self.output.value.take();Ok(#o::receipt(demand))}
   fn close_demands(&self,body:usize)->Result<#v::RetirementDemand,#v::ValueError>{use #o::OwnedFieldReceiving as _;match &self.active{#(#close_demands)*#active::None=>{}}if !self.current.terminal_is_empty(){return self.current.close_demands(body)}if !self.fields.terminal_is_empty(){return self.fields.close_demands(body)}if !self.output.terminal_is_empty(){return self.output.close_demands(body)}self.record.close_demands(body)}
   fn close_step(&mut self,grant:#v::RetainedCloneGrant)->Result<#v::RetainedCloneProgress,#v::ValueError>{use #o::OwnedFieldReceiving as _;if self.terminal_is_empty(){return Ok(Default::default())}let demand=self.close_demands(grant.maximum_copy_bytes)?;if !#o::funds(grant,demand){return Ok(Default::default())}self.closing=true;match &mut self.active{#(#close_step)*#active::None=>{}}if !self.current.terminal_is_empty(){return self.current.close_step(grant)}if !self.fields.terminal_is_empty(){return self.fields.close_step(grant)}if !self.output.terminal_is_empty(){return self.output.close_step(grant)}self.record.close_step(grant)}
   fn terminal_is_empty(&self)->bool{matches!(self.active,#active::None)&&self.current.terminal_is_empty()&&self.fields.terminal_is_empty()&&self.output.terminal_is_empty()&&self.record.terminal_is_empty()}
  }
 };
 (definitions,cursor)
}

pub(super) fn emit_owned_receiving(input:&DeriveInput)->proc_macro2::TokenStream{
 let name=&input.ident;let visibility=&input.vis;let o=quote!(::semio_framework_dsl_record::receiving::owned);let v=quote!(::semio_framework_value);
 match &input.data{
  Data::Struct(data)=>{let(definitions,cursor)=fields_cursor(name,visibility,&data.fields,quote!(#name),"");quote!(#definitions impl #o::DslOwnedReceivingField for #name{type Cursor=#cursor;}impl #o::DslOwnedReceivingRecord for #name{})},
  Data::Enum(data)=>{
   let receiver=borrowed_enum_receiver(data);
   let cursor=quote::format_ident!("__{}OwnedReceiving",name);let mut definitions=Vec::new();let mut variants=Vec::new();let mut selectors=Vec::new();let mut demands=Vec::new();let mut steps=Vec::new();let mut ready=Vec::new();let mut take=Vec::new();let mut close_demands=Vec::new();let mut close_steps=Vec::new();let mut empty=Vec::new();
   for variant in &data.variants{let ident=&variant.ident;let attrs=parse_field_attrs(&variant.attrs);let keyword=attrs.key.unwrap_or_else(||to_kebab(&ident.to_string()));let ty=match &variant.fields{Fields::Unnamed(fields)if fields.unnamed.len()==1=>{let ty=&fields.unnamed[0].ty;variants.push(quote!(#ident(#o::MappedReceiving<#ty,#name>)));selectors.push(quote!(#keyword=>Ok(#cursor::#ident(#o::MappedReceiving::new(#name::#ident)))));None},fields=>{let(body,field_cursor)=fields_cursor(name,visibility,fields,quote!(#name::#ident),&ident.to_string());definitions.push(body);variants.push(quote!(#ident(#field_cursor)));selectors.push(quote!(#keyword=>Ok(#cursor::#ident(Default::default()))));Some(field_cursor)}};let _=ty;demands.push(quote!(Self::#ident(cursor)=>cursor.demands(source,body)));steps.push(quote!(Self::#ident(cursor)=>cursor.step(source,native,body,grant)));ready.push(quote!(Self::#ident(cursor)=>cursor.is_ready()));take.push(quote!(Self::#ident(cursor)=>cursor.take_into(output,grant)));close_demands.push(quote!(Self::#ident(cursor)=>cursor.close_demands(body)));close_steps.push(quote!(Self::#ident(cursor)=>cursor.close_step(grant)));empty.push(quote!(Self::#ident(cursor)=>cursor.terminal_is_empty()));}
   quote!{#(#definitions)*#visibility enum #cursor{#(#variants),*}impl #o::DslOwnedReceivingVariants for #name{type Cursor=#cursor;fn receiving_cursor(keyword:&str)->Result<Self::Cursor,#v::ValueError>{match keyword{#(#selectors,)*_=>Err(#o::invalid())}}}impl #o::OwnedFieldReceiving<#name> for #cursor{
    fn demands(&self,source:&Option<::semio_framework_dsl_record::FieldValue>,body:usize)->Result<#v::RetirementDemand,#v::ValueError>{use #o::OwnedFieldReceiving as _;match #receiver{#(#demands),*}}
    fn step(&mut self,source:&mut Option<::semio_framework_dsl_record::FieldValue>,native:&mut #v::NativeDecodeControl<'_>,body:usize,grant:#v::RetainedCloneGrant)->Result<#v::RetainedCloneProgress,#v::ValueError>{use #o::OwnedFieldReceiving as _;match #receiver{#(#steps),*}}
    fn is_ready(&self)->bool{use #o::OwnedFieldReceiving as _;match #receiver{#(#ready),*}}
    fn take_into(&mut self,output:&mut Option<#name>,grant:#v::RetainedCloneGrant)->Result<#v::RetainedCloneProgress,#v::ValueError>{use #o::OwnedFieldReceiving as _;match #receiver{#(#take),*}}
    fn close_demands(&self,body:usize)->Result<#v::RetirementDemand,#v::ValueError>{use #o::OwnedFieldReceiving as _;match #receiver{#(#close_demands),*}}
    fn close_step(&mut self,grant:#v::RetainedCloneGrant)->Result<#v::RetainedCloneProgress,#v::ValueError>{use #o::OwnedFieldReceiving as _;match #receiver{#(#close_steps),*}}
    fn terminal_is_empty(&self)->bool{use #o::OwnedFieldReceiving as _;match #receiver{#(#empty),*}}
   }}
  },
  _=>syn::Error::new_spanned(input,"owned receiving requires a record or tagged variants").to_compile_error(),
 }
}
